function appPage({ base, csrf, nonce, siteName, domains }) {
  const nav = ['inbox', 'spam', 'archive', 'drafts', 'sent', 'trash'].map(f => `<button class="nb" data-f="${f}" type="button">${ICONS[f]}<span>${f[0].toUpperCase() + f.slice(1)}</span><span class="n" id="n-${f}"></span></button>`).join('');
  const body = `<header class="top glass"><div class="logo">${ICON}</div><div class="brand"><b>${esc(siteName)} Mailbox</b><small>${esc(domains.map(x => '@' + x).join(', '))} · folders, drafts and bot keys</small></div><div class="sp"></div><span class="pill"><span class="dot"></span>Private · owner only</span>
<a class="btn" href="${base}/kb" title="Brain">Brain</a><button class="btn" id="refresh" type="button" title="Refresh"><svg viewBox="0 0 24 24"><path d="M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7"/></svg><span>Refresh</span></button>
<form method="post" action="${base}/logout"><input type="hidden" name="csrf" value="${esc(csrf)}"><button class="btn" type="submit">Sign out</button></form></header>
<main class="app" id="app"><nav class="nav glass" id="nav"><h4>Folders</h4>${nav}<h4>Bots</h4><button class="nb" data-v="bots" type="button">${ICONS.auto}<span>Bots</span></button><button class="nb" data-v="tools" type="button">${ICONS.keys}<span>Tools</span></button><button class="nb" data-v="usage" type="button">${ICONS.auto}<span>Usage</span></button><button class="nb" data-v="keys" type="button">${ICONS.keys}<span>Bot keys</span></button><button class="nb" data-v="auto" type="button">${ICONS.auto}<span>Auto-send</span><span class="n" id="n-auto">OFF</span></button><button class="nb" data-v="log" type="button">${ICONS.log}<span>Activity</span></button>${require('../kbadmin').UI ? `<h4>Knowledge base</h4><a class="nb ext" href="${base}/kb" style="text-decoration:none">${ICONS.archive}<span>Knowledge Base Admin</span></a>` : ''}</nav>
<section class="list glass" id="list"><div class="tools"><label class="search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg><input id="q" type="search" placeholder="Search this folder" autocomplete="off"></label></div><div class="items" id="items"><div class="skel"></div><div class="skel"></div></div><div class="foot" id="foot">Loading…</div></section>
<section class="reader glass" id="reader"><div class="hero"><div><div class="orb"></div><h2>Select a message</h2><p>Nothing is ever deleted at the mail server. Trash only hides a message, and every move can be undone.</p></div></div></section></main>`;
  return shell(siteName + ' Mailbox', `<style>${CSS2}</style>` + body, nonce, CLIENT.replace('__BASE__', JSON.stringify(base)).replace('__CSRF__', JSON.stringify(csrf)));
}
